CREATE VIEW IF NOT EXISTS v_client_financials AS SELECT client, COUNT(*) as consultant_count, COALESCE(SUM(fees),0) as total_fees, COALESCE(SUM(coef_margin),0) as total_margin, COALESCE(SUM(manager_bonus),0) as total_bonus, COALESCE(AVG(julianday('now')-julianday(start_date)),0) as avg_tenure, COALESCE(MAX(julianday('now')-julianday(start_date)),0) as max_tenure FROM consultants WHERE end_date IS NULL OR end_date > datetime('now') GROUP BY client;
CREATE VIEW IF NOT EXISTS v_position_profitability AS SELECT position, COUNT(*) as consultant_count, COALESCE(SUM(fees),0) as total_fees, COALESCE(AVG(coef_percentage),0) as avg_coef, COALESCE(SUM(coef_margin),0) as total_margin FROM consultants WHERE end_date IS NULL OR end_date > datetime('now') GROUP BY position;
